# A thin wrapper: every decision lives in the engine modules named in the `run:`
# lines below, which converge nightly — this file does not, so it must not grow
# logic. This copy is hand-maintained — the canon has no converge — so it is
# edited in the same commit as the stub beside it, and the drift tests in
# packs/claudinite-tasks/test/converge-wiring.test.mjs keep the two honest.
name: Claudinite scheduler

on:
  schedule:
    - cron: '44 5,17 * * *'
  workflow_dispatch:
    inputs:
      wake:
        description: 'Task ids to run now (`pack/task` or a bare task name, space-separated) — wakes each one’s standing item regardless of its anchor'
        required: false
        type: string

concurrency:
  group: claudinite-scheduler-run
  cancel-in-progress: false

permissions:
  contents: write
  issues: write
  pull-requests: write
  actions: write

jobs:
  scheduler-run:
    runs-on: ubuntu-latest
    outputs:
      pickable: ${{ steps.run.outputs.pickable }}
    steps:
      - uses: actions/checkout@v5
      - uses: actions/setup-node@v5
        with:
          node-version: 24
      - name: Instantiate, ready and reclaim work items
        id: run
        env:
          GITHUB_TOKEN: ${{ github.token }}
          CLAUDINITE_WAKE: ${{ inputs.wake }}
          CLAUDINITE_TASKS_SUSPEND_ALL: ${{ vars.CLAUDINITE_TASKS_SUSPEND_ALL }}
        run: node packs/claudinite-tasks/src/schedule/run.mjs

  drain:
    needs: scheduler-run
    # An older member workflow maps no such output, and an empty string is not
    # 'true' — so a stale copy keeps dispatching, the previous behavior and safe.
    if: needs.scheduler-run.outputs.pickable == 'true'
    runs-on: ubuntu-latest
    permissions:
      contents: read
      actions: write
    steps:
      - uses: actions/checkout@v5
      - uses: actions/setup-node@v5
        with:
          node-version: 24
      - name: Start an executor for what this run readied
        env:
          GITHUB_TOKEN: ${{ github.token }}
        run: node packs/claudinite-tasks/src/schedule/drain-dispatch.mjs

  report-failure:
    needs: [scheduler-run, drain]
    # Explicit results rather than `failure()`: `drain` is skipped on a quiet
    # tick, and a bare status function makes this job's fate turn on how the
    # platform propagates a skipped dependency.
    if: >-
      always()
      && (needs.scheduler-run.result == 'failure' || needs.drain.result == 'failure')
    runs-on: ubuntu-latest
    permissions:
      contents: read
      issues: write
    steps:
      - uses: actions/checkout@v5
      - uses: actions/setup-node@v5
        with:
          node-version: 24
      - name: Escalate the failed run to a human-visible issue
        env:
          GITHUB_TOKEN: ${{ github.token }}
        run: node packs/claudinite-tasks/src/recover/workflow-failure.mjs
# A thin wrapper: every decision lives in the engine modules named in the `run:`
# lines below, which converge nightly — this file does not, so it must not grow
# logic. This copy is hand-maintained — the canon has no converge — so it is
# edited in the same commit as the stub beside it.
name: Claudinite executor

on:
  issues:
    types: [labeled]
  workflow_dispatch:
    inputs:
      continuation_depth:
        description: 'How many dead runs this chain has continued through — set by the continuation job below, never by hand'
        required: false
        type: string

permissions:
  contents: write
  issues: write
  pull-requests: write
  actions: write

jobs:
  execute:
    # A workflow's event trigger names label strings LITERALLY — nothing here
    # decodes. The legacy `task:ready` stood beside this one while a fielded engine
    # could still write it; no member stamps such a version any more (#1119).
    if: >-
      github.event_name == 'workflow_dispatch'
      || github.event.label.name == 'task:status:waiting-for-executor'
      || github.event.label.name == 'task:urgent'
    runs-on: ubuntu-latest
    # A backstop against a wedged runner, well clear of any declared
    # `code_work_timeout`; the heartbeat's leash is what bounds real work.
    timeout-minutes: 350
    steps:
      - uses: actions/checkout@v5
      - uses: actions/setup-node@v5
        with:
          node-version: 24
      - name: Pick up and execute ready work
        env:
          GITHUB_TOKEN: ${{ github.token }}
          CLAUDINITE_TASKS_SUSPEND_ALL: ${{ vars.CLAUDINITE_TASKS_SUSPEND_ALL }}
          # Every repository VARIABLE, as one static line (#1492). Unlike the secrets
          # below this never changes: `vars` is the context GitHub's own docs define as
          # non-sensitive and render unmasked in logs, so serialising it is not the
