    29	export const heartbeatComment = ({ executor, at, minutes }) =>
    30	  `${HEARTBEAT_MARKER}\nStill working: executor \`${executor}\`, ${minutes} minute(s) in, at ${at}.`;
    31	
    32	// When the current holder last said anything — the newest live claim or heartbeat.
    33	// A struck comment is not a signal: it says its author let the item go.
    34	export function lastLivenessAt(comments = []) {
