  for (const item of deadAgentItems(open, now, { progressAt })) {
    if (!claim(item)) continue;
    ops.push({
      kind: 'escalate', issue: item.number, from: STATUS_RUNNING_AGENT,
      to: STATUS_NEEDS_HUMAN_FAILURE, wedged: progressAt(item) != null, body: null,
    });
  }

