test('a superseded park is closed as superseded, not as abandoned', async () => {
  const done = { ...workItem(99, [STATUS_DONE]), state: 'closed', closed_at: '2026-07-20T00:00:00Z', updated_at: '2026-07-20T00:00:00Z' };
