22	// what the task says is the seam's, and a run with a task to ask needs one.
23	const yes = async () => ({ run: true, reason: 'work exists' });
24	const no = async () => ({ run: false, reason: 'quiet' });
25	const askedIds = () => { const seen = []; return { seen, evaluate: async (t) => { seen.push(t.id); return { run: true, reason: 'work exists' }; } }; };
