1	// THE REPAIR PHASE of the scheduler run (docs/PRINCIPLES.md) — the recovery that
2	// used to run once a day as a task of its own, planned here as ops the same run
3	// applies before it asks any task whether it wants to run.
4	//
5	// IT IS STILL A FALLBACK. Every rule below repairs something that already went
6	// wrong — a label swap that tore, a session that died, a park nobody answered, a
7	// terminal nobody closed — and the healthy flow of a task never passes through
8	// here: an item the machinery handled correctly is settled by whoever handled it,
9	// before any of this runs. A new rule here is a claim that a failure mode exists
10	// and that nothing nearer to it can close it out; the alternative to writing one
11	// is usually fixing the flow that left the mess. What changed when this moved is
12	// its siting and its latency, not its standing.
13	//
14	// AND IT ONLY EVER READS OPEN ITEMS. An item somebody closed is finished, park
15	// label and all: a person ending a park by closing its issue is an answer, not a
16	// state to repair, and nothing here reopens, re-labels or re-nags one.
17	//
18	// WHY IT RUNS BEFORE THE ASK. Repair frees what the ask then reads: closing an
19	// abandoned failure park releases the task's lane, and the occurrence the task is
20	// owed is filed in the same run rather than one tick later. That ordering is the
21	// whole reason this is a phase of the run and not a task behind it — a task's own
22	// repair could only ever land after the tick that filed it, and could never feed
23	// the drain gate that dispatches an executor for what it freed.
24	//
25	// The verdicts stay pure in `./repair-rules.mjs`; this module decides
26	// which op each verdict becomes and which of them may be threaded back into the
27	// item list the ask reads. The shell in `run.mjs` does the GitHub I/O.
28	
29	import {
30	  staleReadyItems, staleReadyComment, deadAgentItems, deadAgentComment,
31	  statelessItems, statelessComment, supersededItems, supersededComment, taskPathIndex,
32	  orphanedParkItems, orphanedParkComment, endedParkItems, endedParkComment,
33	  abandonedParkItems, abandonedParkComment, unclosedTerminalItems, unclosedTerminalComment,
34	  periodForTasks, scheduledForTasks,
35	} from './repair-rules.mjs';
36	import {
37	  STATUS_READY, STATUS_RUNNING_AGENT, STATUS_DONE, STATUS_REJECTED,
38	  STATUS_NEEDS_HUMAN_ACTION, STATUS_NEEDS_HUMAN_FAILURE, IN_REVIEW_LABEL,
39	} from '../../public/task-constants.mjs';
40	import {
41	  statusOf, parseWorkItemTitle, parseWorkItemBody, taskIdFromPath, spellingsOf,
42	} from '../../public/work-item-grammar.mjs';
43	
44	// The three ops this phase emits, each a label-and-body mechanic `run.mjs` applies:
45	//   { kind: 'escalate', issue, from, to, body }        status -> a park, item stays open
46	//   { kind: 'retire',   issue, from, to, body, close } status -> a terminal, issue closes
47	//   { kind: 'close-terminal', issue, body, close }     the close a torn transition never made
48	//
49	// `confirm` names the pure predicate the shell must see hold on a FRESH read before
50	// it writes. Only the three rules whose premise is a TRANSIENT carry one — "this
51	// looks torn", "nobody has touched this" — because a swap in flight is
52	// indistinguishable from one that tore and `items` is a snapshot seconds old (#1104:
53	// #1101 closed `task:done` at 12:50:13Z and was escalated at 12:50:21Z). The rules
54	// that turn on a clock over a stable label need no second read.
55	//
56	// `clearInReview` is the one write that lands on a DIFFERENT issue than the one the
57	// rule judged (a legacy shadow item's request issue, below).
58	
59	// Whether the ask may see this op's effect in the same run. An op the shell might
60	// decline on its fresh read must NOT be threaded: the plan would then hand the ask
61	// a world the run never wrote. Declining to thread costs at most one tick of lag on
62	// a rule that is already measured in hours or days, which is the safe direction.
63	const threadable = (op) => !op.confirm;
64	
65	// Apply an op's effect to the in-memory item, mirroring exactly what the shell
66	// writes — status cleared of EVERY spelling, the new label added, and for a retire
67	// the close itself. The cadence terms read these items (`signals/index.mjs` folds
68	// `ctx.items` into each task's run history), so an effect that is written to GitHub
69	// but not to the snapshot leaves the ask judging a world one write out of date.
70	function threadEffect(item, op) {
71	  if (op.from) {
72	    const gone = new Set(spellingsOf(op.from));
73	    item.labels = item.labels.filter((l) => !gone.has(l));
74	  }
75	  if (op.to && !item.labels.includes(op.to)) item.labels.push(op.to);
76	  if (op.kind === 'retire') {
77	    item.state = 'closed';
78	    item.closed_at = op.at;
79	  }
80	}
81	
82	// The whole phase. `open` is the open half of `items`; every lookup a rule needs
83	// that is not a label is injected, so the rules stay pure and the reads stay the
84	// shell's:
85	//   progressAt(item)   the newest progress comment on an item holding an agent
86	//   resolutionOf(n)    'merged' | 'closed' | null for a park's `Ends-when:` target
87	//   doneAfter(id, at)  the task's newest clean run closed after `at`, or null
88	//   isRequest(number)  true where job 4 owns this issue (below)
89	export function planRepair({
90	  items = [], tasks = [], now, progressAt = () => null, resolutionOf = () => null,
91	  doneAfter = () => null, isRequest = () => false,
92	}) {
93	  const open = items.filter((i) => i.state === 'open');
94	  const ops = [];
95	  const taken = new Set();
96	  const claim = (item) => { if (taken.has(item.number)) return false; taken.add(item.number); return true; };
97	
98	  // --- the closing rules, in their precedence order -------------------------
99	  // Naming the run that answered a park says more than naming the absence of a
100	  // task file, which says more than the clock running out on it.
101	  for (const item of supersededItems(open, { doneAfter })) {
102	    if (!claim(item)) continue;
103	    const p = parseWorkItemTitle(item.title) ?? taskIdFromPath(parseWorkItemBody(item.body).taskPath);
104	    const run = doneAfter(`${p.pack}/${p.task}`, item.updated_at ?? item.created_at);
105	    ops.push({
106	      kind: 'retire', rule: 'superseded', issue: item.number, from: statusOf(item), to: STATUS_REJECTED,
107	      close: 'not_planned', at: now, body: supersededComment(run),
108	    });
109	  }
110	
111	  const headPath = taskPathIndex(tasks);
112	  for (const item of orphanedParkItems(open, { tasks })) {
113	    if (!claim(item)) continue;
114	    const p = parseWorkItemTitle(item.title) ?? taskIdFromPath(parseWorkItemBody(item.body).taskPath);
115	    const id = `${p.pack}/${p.task}`;
116	    ops.push({
117	      kind: 'retire', rule: 'orphaned', issue: item.number, from: statusOf(item), to: STATUS_REJECTED,
118	      close: 'not_planned', at: now, body: orphanedParkComment(id, headPath.get(id) ?? null),
119	    });
120	  }
121	
122	  // THE RESOLUTION DECIDES THE OUTCOME; BOTH OUTCOMES CLOSE. A merged target means
123	  // the work landed and an unmerged one that it was rejected — and a person who
124	  // closed the pull request has already given their answer, so leaving their issue
125	  // open asks them to come back and say it a second time.
126	  for (const item of endedParkItems(open, { resolutionOf })) {
127	    if (!claim(item)) continue;
128	    const { endsWhen, request } = parseWorkItemBody(item.body);
129	    const resolution = resolutionOf(endsWhen);
130	    ops.push({
131	      kind: 'retire', rule: 'ended', issue: item.number, from: statusOf(item),
132	      to: resolution === 'merged' ? STATUS_DONE : STATUS_REJECTED,
133	      close: resolution === 'merged' ? 'completed' : 'not_planned',
134	      at: now, body: endedParkComment(endsWhen, resolution),
135	      // A LEGACY SHADOW ITEM told its request issue it was in review; nothing else
136	      // would ever take that back, and the review is over.
137	      clearInReview: request && request !== item.number ? { issue: request, label: IN_REVIEW_LABEL } : null,

