1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { planRepair } from '../../src/schedule/repair.mjs';
4	import { applyRepairOp } from '../../src/schedule/run.mjs';
5	import { doneRunLookup, SUPERSEDABLE_PARKS } from '../../src/schedule/repair-rules.mjs';
6	import { lastProgressAt } from '../../src/items/heartbeat.mjs';
7	import {
8	  STATUS_NEEDS_HUMAN_ACTION, STATUS_NEEDS_HUMAN_FAILURE, HANDOFF_MARKER, STATUS_DONE,
9	  STATUS_REJECTED,
10	} from '../../public/task-constants.mjs';
11	import { parkKindOf, isStatus } from '../../public/work-item-grammar.mjs';
12	import { comment, addLabel, removeLabel, closeIssue } from '../../src/world/github.mjs';
13	
14	// A fake GitHub that answers the one read the repair phase makes at WRITE time —
15	// the fresh re-read the three transient rules confirm against — and records the
16	// writes. `labelsOn` is what the assertions turn on: a park is the state the machine
17	// reads and what the human is being asked for, in one label.
18	// `fresh` answers that per-issue re-read, keyed by number, so a test can say "this
19	// item looks different by the time the run writes".
20	function repairGh(issues, fresh = {}) {
21	  const added = [];
22	  const patched = [];
23	  const posted = [];
24	  const gh = async (path, { method = 'GET', body } = {}) => {
25	    if (method === 'PATCH' && /\/issues\/\d+$/.test(path)) {
26	      patched.push({ issue: Number(path.match(/issues\/(\d+)/)[1]), ...body });
27	    }
28	    if (method === 'GET' && /\/issues\/\d+$/.test(path)) {
29	      const n = Number(path.match(/issues\/(\d+)/)[1]);
30	      return { status: 200, json: fresh[n] ?? issues.find((i) => i.number === n) ?? {} };
31	    }
32	    if (method === 'POST' && /\/issues\/\d+\/comments$/.test(path)) posted.push(body.body);
33	    if (method === 'POST' && /\/issues\/\d+\/labels$/.test(path)) {
34	      added.push({ issue: Number(path.match(/issues\/(\d+)/)[1]), labels: body.labels });
35	    }
36	    return { status: method === 'POST' ? 201 : 200, json: {} };
37	  };
38	  return { gh, added, patched, posted };
39	}
40	
41	const at = (iso) => iso;
42	const workItem = (number, labels, { created = '2026-07-01T00:00:00Z', updated = created, body = 'packs/p/tasks/a/task.md\n' } = {}) => ({
43	  number, title: '[claudinite-work] p/a', body, labels: labels.map((name) => ({ name })),
44	  state: 'open', created_at: created, updated_at: updated, pull_request: undefined,
45	});
46	
47	const quiet = async (fn) => {
48	  const real = console.log;
49	  console.log = () => {};
50	  try { return await fn(); } finally { console.log = real; }
51	};
52	
53	// ONE label per park since the write-side flip (#1119): the park IS the status.
54	const labelsOn = (added, issue) => added.filter((a) => a.issue === issue).flatMap((a) => a.labels);
55	
56	// The phase as the scheduler run drives it: plan over the items, then apply every op
57	// through the real write paths. The seams are built here exactly as `run.mjs` builds
58	// them from its own reads, so a case exercises the wiring rather than a paraphrase
59	// of it.
60	async function repair(issues, { now, tasks = [], comments = {}, fresh = {}, targets = {}, closed = [], blockers = {} } = {}) {
61	  const { gh, added, patched, posted } = repairGh(issues, fresh);
62	  const items = [...issues, ...closed];
63	  const agentComments = new Map(Object.entries(comments).map(([n, c]) => [Number(n), c]));
64	  const plan = planRepair({
65	    items, tasks, now,
66	    progressAt: (item) => lastProgressAt(agentComments.get(item.number) ?? []),
67	    resolutionOf: (n) => targets[n] ?? null,
68	    doneAfter: doneRunLookup(closed.filter((i) => isStatus(i, STATUS_DONE))),
69	    stateOf: (n) => blockers[n] ?? 'open',
70	  });
71	  const written = [];
72	  for (const op of plan.ops) {
73	    const ok = await applyRepairOp({
74	      gh, repo: 'o/r', op, now, tasks, agentComments, log: () => {},
75	      api: { comment, addLabel, removeLabel, closeIssue },
76	    });
77	    if (ok) written.push(op);
78	  }
79	  const by = (rule) => written.filter((o) => o.rule === rule).map((o) => o.issue);
80	  return {
81	    added, patched, posted, ops: plan.ops, threadedClosed: plan.closed,
82	    staleReady: by('stale-ready'), deadAgents: by('dead-agent'), stateless: by('stateless'),
83	    superseded: by('superseded'), orphaned: by('orphaned'), ended: by('ended'),
84	    abandoned: by('abandoned'), unclosed: by('unclosed'), stuck: by('stuck-dependency'),
85	  };
86	}
87	
88	test('a stale-ready item parks at action — the lane is not being drained, and the fix is outside the item', async () => {
89	  const out = await quiet(() => repair([workItem(11, ['task:status:waiting-for-executor'], { created: '2026-07-01T00:00:00Z' })],
90	    { now: at('2026-07-10T00:00:00Z') }));
91	  assert.deepEqual(out.staleReady, [11]);
92	  assert.deepEqual(labelsOn(out.added, 11), [STATUS_NEEDS_HUMAN_ACTION]);
93	});
94	
95	// A dead session is the machine noticing a corpse, not a person deciding anything.
96	// The kind matters twice over: `failure` is the only park a later clean run can
97	// supersede (rule E), and the only one that holds the task's lane so the generator
98	// stops filing a fresh occurrence every anchor behind a run nobody has looked at.
99	test('a dead agent claim parks at failure — nothing here is a human\'s choice', async () => {
